#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

using namespace std;

const int MAXN = 66;

int r, c, n;
string s;
long long comb[MAXN][MAXN];

int cnt_a[MAXN], cnt_b[MAXN];
vector<long long> partial[MAXN], partial_zero[MAXN];

void compute_comb() {
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

long long get_difs(int conf, int a_bef, int b_bef) {
    long long total = 0;
    for (int i = 0; i <= c; ++i) {
        if (conf & (1 << i)) {
            b_bef++;
            long long aux1 = comb[b_bef - 1][r - 1];
            long long aux2 = comb[n - b_bef][r] - comb[a_bef][r];
            total -= aux1 * aux2;
        } else {
            a_bef++;
            long long aux1 = comb[a_bef - 1][r - 1];
            long long aux2 = comb[n - a_bef][r] - comb[b_bef][r];
            total += aux1 * aux2;
        }
    }
    return total;
}

bool check_conf(int conf) {
    for (int i = 0; i <= c; ++i) {
        if (s[2 * r + c + i] == 'A' && ((conf >> i) & 1) == 1) return false;
        if (s[2 * r + c + i] == 'B' && ((conf >> i) & 1) == 0) return false;
    }
    return true;
}

void compute_second_part() {
    int limit = 1 << (c + 1);
    for (int conf = 0; conf < limit; ++conf) {
        int b_here = __builtin_popcount(conf);
        int a_here = c + 1 - b_here;
        if (check_conf(conf))
            partial[a_here].push_back(get_difs(conf, r + c - a_here, r + c - b_here));
        else
            partial_zero[a_here].push_back(get_difs(conf, r + c - a_here, r + c - b_here));
    }
    for (int i = 0; i <= c + 1; ++i) {
        sort(partial[i].begin(), partial[i].end());
        sort(partial_zero[i].begin(), partial_zero[i].end());
    }
}

long long get_coef(int conf) {
    int i;
    for (i = 0; i <= c; ++i) {
        if ( ((conf >> i) & 1) != (conf & 1) ) break;
    }
    for (int j = i; j <= c; ++j) {
        if (s[2 * r - 1 + j] == 'A' && (((conf >> j) & 1) == 1)) return 0;
        if (s[2 * r - 1 + j] == 'B' && (((conf >> j) & 1) == 0)) return 0;
    }
    int set_a = r - 1 + ( (conf & 1) == 0 ? i : 0 );
    int set_b = r - 1 + ( (conf & 1) == 1 ? i : 0 );
    if (set_a < cnt_a[2 * r - 2 + i]) return 0;
    if (set_b < cnt_b[2 * r - 2 + i]) return 0;
    int total = set_a + set_b - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i];
    return comb[total][set_a - cnt_a[2 * r - 2 + i]];
}

void update_pair(pair<long long, long long>& ans, pair<long long, long long> act) {
    if (act.first < 0) act.first = -act.first;
    if (ans.first > act.first) {
        ans = act;
    } else if (ans.first == act.first) {
        ans.second += act.second;
    }
}

long long count_in_vector(const vector<long long>& data, long long val) {
    auto lower = lower_bound(data.begin(), data.end(), val);
    auto upper = upper_bound(data.begin(), data.end(), val);
    return upper - lower;
}

long long compute_first_part() {
    int limit = 1 << (c + 1);
    pair<long long, long long> answer = {1LL << 60, 0};
    for (int conf = 0; conf < limit; ++conf) {
        int b_here = __builtin_popcount(conf);
        int a_here = c + 1 - b_here;
        long long act = get_difs(conf, r - 1, r - 1);
        long long coef = get_coef(conf);
        auto it = lower_bound(partial[c + 1 - a_here].begin(), partial[c + 1 - a_here].end(), -act);
        if (it != partial[c + 1 - a_here].end()) {
            long long val = *it + act;
            if (abs(val) <= answer.first) {
                long long count_coef = count_in_vector(partial[c + 1 - a_here], *it);
                update_pair(answer, {abs(val), coef * count_coef});
            }
        }
        if (it != partial[c + 1 - a_here].begin()) {
            --it;
            long long val = *it + act;
            if (abs(val) <= answer.first) {
                long long count_coef = count_in_vector(partial[c + 1 - a_here], *it);
                update_pair(answer, {abs(val), coef * count_coef});
            }
        }
        // Zero coefficient branch
        long long zero_coef = 0;
        auto it_zero = lower_bound(partial_zero[c + 1 - a_here].begin(), partial_zero[c + 1 - a_here].end(), -act);
        if (it_zero != partial_zero[c + 1 - a_here].end()) {
            long long val = *it_zero + act;
            long long count_coef = count_in_vector(partial[c + 1 - a_here], *it_zero);
            if (abs(val) <= answer.first) {
                update_pair(answer, {abs(val), zero_coef * count_coef});
            }
        }
        if (it_zero != partial_zero[c + 1 - a_here].begin()) {
            --it_zero;
            long long val = *it_zero + act;
            long long count_coef = count_in_vector(partial[c + 1 - a_here], *it_zero);
            if (abs(val) <= answer.first) {
                update_pair(answer, {abs(val), zero_coef * count_coef});
            }
        }
    }
    return answer.second;
}

int main() {
    cin >> r >> c >> s;
    n = 2 * (r + c);
    compute_comb();
    for (int i = 1; i <= n; ++i) {
        cnt_a[i] = cnt_a[i - 1] + (s[i - 1] == 'A' ? 1 : 0);
        cnt_b[i] = cnt_b[i - 1] + (s[i - 1] == 'B' ? 1 : 0);
    }
    compute_second_part();
    long long result = compute_first_part();
    cout << result;
    return 0;
}
